INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('21', 'Swapped', '1007757', 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', 'A small woodland creature and a majestic bird, two natural sworn enemies of the Valley, magically trade places and set off on an adventure of a lifetime to switch back. Their journey soon uncovers a greater threat—one that could endanger not only their species, but the entire valley they call home.', '2026', NULL, 'assets/posters/1007757.jpg', NULL, NULL, 'assets/fanart/backgrounds/1007757.jpg', 'assets/fanart/logos/1007757.png', '162313', '351506', '1e2d2c', '4d3c29', NULL, '1', '2026-06-02 18:28:39', '0', '8.97', '0', '2026-06-02 18:28:39', '2026-06-02 18:28:39');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('22', 'The Shawshank Redemption', '278', 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.', '1994', NULL, 'assets/posters/278.jpg', NULL, NULL, 'assets/fanart/backgrounds/278.jpg', 'assets/fanart/logos/278.png', '21211f', '563b29', '4c3f38', '47403f', NULL, '1', '2026-06-02 18:28:44', '0', '8.72', '0', '2026-06-02 18:28:44', '2026-06-02 18:28:44');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('23', 'The Godfather', '238', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.', '1972', NULL, 'assets/posters/238.jpg', NULL, NULL, 'assets/fanart/backgrounds/238.jpg', 'assets/fanart/logos/238.png', '0b0b0b', '660507', '660507', '2f2f2f', NULL, '1', '2026-06-02 18:28:48', '0', '8.70', '0', '2026-06-02 18:28:48', '2026-06-02 18:28:48');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('24', 'Project Hail Mary', '687163', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '2026', NULL, 'assets/posters/687163.jpg', NULL, NULL, 'assets/fanart/backgrounds/687163.jpg', 'assets/fanart/logos/687163.png', '111f0c', '17240f', '27372b', '1d1007', NULL, '1', '2026-06-02 18:28:54', '0', '8.65', '0', '2026-06-02 18:28:54', '2026-06-02 18:28:54');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('25', 'The Godfather Part II', '240', 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.', 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.', '1974', NULL, 'assets/posters/240.jpg', NULL, NULL, 'assets/fanart/backgrounds/240.jpg', 'assets/fanart/logos/240.png', '17090c', '0c1313', '14121b', '180908', NULL, '1', '2026-06-02 18:28:58', '0', '8.57', '0', '2026-06-02 18:28:58', '2026-06-02 18:28:58');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('26', 'Schindler\'s List', '424', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.', '1993', NULL, 'assets/posters/424.jpg', NULL, NULL, 'assets/fanart/backgrounds/424.jpg', 'assets/fanart/logos/424.png', '0b0b0b', '131313', '131313', '030303', NULL, '1', '2026-06-02 18:29:03', '0', '8.57', '0', '2026-06-02 18:29:03', '2026-06-02 18:29:03');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('27', '12 Angry Men', '389', 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father. What begins as an open and shut case soon becomes a mini-drama of each of the jurors\' prejudices and preconceptions about the trial, the accused, and each other.', 'The defense and the prosecution have rested and the jury is filing into the jury room to decide if a young Spanish-American is guilty or innocent of murdering his father. What begins as an open and shut case soon becomes a mini-drama of each of the jurors\' prejudices and preconceptions about the trial, the accused, and each other.', '1957', NULL, 'assets/posters/389.jpg', NULL, NULL, 'assets/fanart/backgrounds/389.jpg', 'assets/fanart/logos/389.png', '360300', '660803', '660f04', '65170f', NULL, '1', '2026-06-02 18:29:12', '0', '8.56', '0', '2026-06-02 18:29:12', '2026-06-02 18:29:12');
