INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('29', 'Spirited Away', '129', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.', '2001', NULL, 'assets/posters/129.jpg', NULL, NULL, 'assets/fanart/backgrounds/129.jpg', 'assets/fanart/logos/129.png', '012432', '604932', '0a2746', '053b55', NULL, '1', '2026-06-02 18:29:18', '0', '8.54', '0', '2026-06-02 18:29:18', '2026-06-02 18:29:18');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('30', 'The Dark Knight', '155', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.', '2008', NULL, 'assets/posters/155.jpg', NULL, NULL, 'assets/fanart/backgrounds/155.jpg', 'assets/fanart/logos/155.png', '132132', '371e29', '3d4056', '1c475f', NULL, '1', '2026-06-02 18:29:23', '0', '8.53', '0', '2026-06-02 18:29:23', '2026-06-02 18:29:23');
INSERT IGNORE INTO dbProj_movies (movie_id, title, tmdb_id, short_description, synopsis, release_year, duration_min, image_url, media_url, download_url, fanart_bg, fanart_logo, color_tl, color_tr, color_br, color_bl, created_by, is_published, published_at, view_count, avg_rating, rating_count, created_at, updated_at) VALUES ('31', 'Dilwale Dulhania Le Jayenge', '19404', 'Raj is a rich, carefree, happy-go-lucky second generation NRI. Simran is the daughter of Chaudhary Baldev Singh, who in spite of being an NRI is very strict about adherence to Indian values. Simran has left for India to be married to her childhood fiancé. Raj leaves for India with a mission at his hands, to claim his lady love under the noses of her whole family. Thus begins a saga.', 'Raj is a rich, carefree, happy-go-lucky second generation NRI. Simran is the daughter of Chaudhary Baldev Singh, who in spite of being an NRI is very strict about adherence to Indian values. Simran has left for India to be married to her childhood fiancé. Raj leaves for India with a mission at his hands, to claim his lady love under the noses of her whole family. Thus begins a saga.', '1995', NULL, 'assets/posters/19404.jpg', NULL, NULL, 'assets/fanart/backgrounds/19404.jpg', 'assets/fanart/logos/19404.png', '2a171a', '492d33', '462521', '27171a', NULL, '1', '2026-06-02 18:29:29', '0', '8.51', '0', '2026-06-02 18:29:29', '2026-06-02 18:29:29');
